// ModerationQueueUpdate subscribes to moderation queue updates
func (r *subscriptionResolver) ModerationQueueUpdate(ctx context.Context, priority *model.Priority) (<-chan *model.ModerationItem, error) {
	r.Logger.Info("Starting moderation queue subscription",
		zap.String("priority", func() string {
			if priority != nil {
				return string(*priority)
			}
			return QueryTypeAll
		}()))

	// Track the subscription cost
	_ = r.CostTracker.TrackDynamoRead(1)

	// Create channel for updates
	ch := make(chan *model.ModerationItem, 10)

	// Subscribe to moderation events from streams processor
	go func() {
		defer close(ch)

		// Listen for real-time moderation events
		for {
			select {
			case <-ctx.Done():
				return
			default:
				// Get recent moderation items matching priority
				items, err := r.getModerationUpdates(ctx, priority)
				if err != nil {
					r.Logger.Error("failed to get moderation updates", zap.Error(err))
					continue
				}

				for _, item := range items {
					select {
					case ch <- item:
					case <-ctx.Done():
						return
					}
				}

				time.Sleep(5 * time.Second) // Poll every 5 seconds
			}
		}
	}()

	return ch, nil
}

// ThreatIntelligence subscribes to threat intelligence alerts
func (r *subscriptionResolver) ThreatIntelligence(ctx context.Context) (<-chan *model.ThreatAlert, error) {
	r.Logger.Info("Starting threat intelligence subscription")

	_ = r.CostTracker.TrackDynamoRead(1)

	ch := make(chan *model.ThreatAlert, 10)

	go func() {
		defer close(ch)

		for {
			select {
			case <-ctx.Done():
				return
			default:
				alerts, err := r.getThreatAlerts(ctx)
				if err != nil {
					r.Logger.Error("failed to get threat alerts", zap.Error(err))
					continue
				}

				for _, alert := range alerts {
					select {
					case ch <- alert:
					case <-ctx.Done():
						return
					}
				}

				time.Sleep(10 * time.Second) // Less frequent polling
			}
		}
	}()

	return ch, nil
}

