func (r *queryResolver) calculatePeriodStart(endTime time.Time, period model.TimePeriod) time.Time {
	switch period {
	case model.TimePeriodHour:
		return endTime.Add(-1 * time.Hour)
	case model.TimePeriodDay:
		return endTime.Add(-24 * time.Hour)
	case model.TimePeriodWeek:
		return endTime.Add(-7 * 24 * time.Hour)
	case model.TimePeriodMonth:
		return endTime.Add(-30 * 24 * time.Hour)
	default:
		return endTime.Add(-24 * time.Hour)
	}
}

func (r *queryResolver) getFederationVolumeByHour(ctx context.Context, startTime, endTime time.Time) []*model.HourlyVolume {
	// Get federation metrics
	stats, err := r.Storage.Federation().GetFederationStatistics(ctx, startTime, endTime)
	if err != nil {
		r.Logger.Error("failed to get federation volume", zap.Error(err))
		return []*model.HourlyVolume{}
	}

	// Aggregate by hour - use stats to calculate hourly volumes
	hourlyMap := make(map[time.Time]int)
	// In a real implementation, would have detailed time-series data
	// For now, distribute the total counts across the time period
	if stats != nil {
		totalMessages := stats.TotalMessages
		hoursInPeriod := int(endTime.Sub(startTime).Hours())
		if hoursInPeriod > 0 {
			messagesPerHour := totalMessages / int64(hoursInPeriod)
			for hour := startTime; hour.Before(endTime); hour = hour.Add(time.Hour) {
				hourlyMap[hour.Truncate(time.Hour)] = int(messagesPerHour)
			}
		}
	}

	// Convert to GraphQL format
	volumes := make([]*model.HourlyVolume, 0)
	for hour := startTime; hour.Before(endTime); hour = hour.Add(time.Hour) {
		count := hourlyMap[hour.Truncate(time.Hour)]
		volumes = append(volumes, &model.HourlyVolume{
			Hour:       model.Time(hour),
			Inbound:    count / 2, // Split between inbound/outbound
			Outbound:   count / 2,
			Errors:     0,
			AvgLatency: 50.0, // Default 50ms
		})
	}

	return volumes
}

