func (r *queryResolver) calculateOverallHealth(services []*model.ServiceStatus, databases []*model.DatabaseStatus, queues []*model.QueueStatus) bool {
	// All services must be healthy for overall health
	for _, svc := range services {
		if svc.Status != model.HealthStatusHealthy {
			return false
		}
	}

	for _, db := range databases {
		if db.Status != model.HealthStatusHealthy {
			return false
		}
	}

	for _, q := range queues {
		// Queues don't have a status field, check depth instead
		if q.Depth > 1000 {
			return false
		}
	}

	return true
}

